const rowApplies = (row, answers, evaluation) =>
  row.applies?.(answers, evaluation) ?? true

const extraAnswerGiven = (row, answers, evaluation) =>
  row.extraAnswerGiven?.(answers, evaluation) ?? true

export const rowStatus = (row, answers, inScope, evaluation) => {
  if (!rowApplies(row, answers, evaluation)) {
    return NA
  }
  const status = statusOf(rowParts(row), answers, inScope, evaluation)
  return status === FULFILLED && !extraAnswerGiven(row, answers, evaluation)
    ? IN_PROGRESS
    : status
}

const inScopeParts = parts.filter((part) => inScope.has(partKey(part)))
  if (inScopeParts.length === 0) {
    return NA
  }

  const required = inScopeParts.filter((part) => partRequired(part, evaluation))
  const started = inScopeParts.some((part) => partStarted(part, answers))

  return required.length === 0
    ? optionalOrProgressStatus(inScopeParts, started, answers, evaluation)
    : requiredPartsStatus(required, started, answers, evaluation)

/** The task-row ids whose stored answers no longer pass their own page's
 * rules — what the hub demotes back to "To do" however the engine still
 * counts them. */
export const invalidRowIds = async (answers, context) => {
  const invalid = new Set()
  for (const row of taskRows) {
    if (hasErrors(await rowStoredErrors(row, answers, context))) {
      invalid.add(row.id)
    }
  }
  return invalid
}

export const rowStoredErrors = async (row, answers, context) => {
  let merged = NO_ERRORS
  for (const page of row.pages) {
    const validation = validationOf(page.id)
    if (!validation) {
      continue
    }
    const { errors } = await validation.onStored(answers, context)
    if (hasErrors(errors)) {
      merged = merged === NO_ERRORS ? errors : { ...merged, ...errors }
    }
  }
  return merged
}

/** The review page's cards whose stored answers no longer pass their rows'
 * rules, keyed to the first message their rows produced — a card names one
 * broken answer, not every one behind it. */

export const guardedJourneyPath = (path) => {
  const prefix = journeyPrefix()
  if (!path.startsWith(prefix) || path === createPath()) {
    return false
  }
  const [journeyId, ...slugParts] = path.slice(prefix.length).split('/')
  const slug = slugParts.join('/')
  if (ACTION_SLUGS.has(slug)) {
    return false
  }
  const isEntrySurface =
    slug === originPage.slug || slug.startsWith(`${originPage.slug}/`)
  return Boolean(journeyId) && !isEntrySurface
}

export const entryGuardTarget = async (request, h) => {
  if (!guardedJourneyPath(request.path)) {
    return null
  }
  const { journey, answers } = await get(request, h)
  if (hasCommittedNotificationAnswers(answers)) {
    return null
  }
  request.logger.info(
    { journeyId: journey.journeyId, path: request.path },
    'No answer entered, sent to the first page'
  )
  return pagePath(request.params.journeyId, originPage.slug)
}

const userEntered = (key) => {
