  if (href) {
    globalThis.location.replace(href)
  }
}

const readStatuses = async () => {
  try {
    const response = await fetch(STATUS_ENDPOINT, {
      headers: { Accept: 'application/json' }
    })
    if (!response.ok) {
      return null
    }
    const { documents } = await response.json()
    return documents ?? null
  } catch {
    return null
  }
}

